.darma-loader-tw-search-scan { position: relative; display: inline-block; width: var(--loader-size, 64px); height: var(--loader-size, 64px); animation: darma-loader-tw-search-scan-twScan calc(var(--loader-speed, 1s) * 2) ease-in-out infinite; }
.darma-loader-tw-search-scan .darma-loader-tw-search-scan__lens { position: absolute; left: 6%; top: 6%; width: 64%; height: 64%; border-radius: 9999px; border: calc(var(--loader-size, 64px) * .07) solid var(--loader-color, #f59e0b); overflow: hidden; box-sizing: border-box; }
.darma-loader-tw-search-scan .darma-loader-tw-search-scan__lens i { position: absolute; left: 0; right: 0; height: calc(var(--loader-size, 64px) * .05); background: color-mix(in srgb, var(--loader-color, #f59e0b) 60%, transparent); animation: darma-loader-tw-search-scan-twScanLine calc(var(--loader-speed, 1s) * 1.2) ease-in-out infinite; }
.darma-loader-tw-search-scan::after { content: ''; position: absolute; right: 10%; bottom: 12%; width: 30%; height: calc(var(--loader-size, 64px) * .07); border-radius: 9999px; background: var(--loader-color, #f59e0b); transform-origin: right center; transform: rotate(45deg); }
@keyframes darma-loader-tw-search-scan-twScan { 0%, 100% { transform: translate(0, 0); } 50% { transform: translate(7%, 7%); } }
@keyframes darma-loader-tw-search-scan-twScanLine { 0%, 100% { top: 8%; } 50% { top: 76%; } }

